Object.assign(window.TEM8_DICTIONARY, {"vast":{"media":{"uk":"media/uk/vast__gb_1.mp3","us":"media/us/vast__us_1.mp3"},"oxford":{"phon":"vɑːst","pos":"adj.","senses":[{"en":"extremely large in area, size, amount, etc.","cn":"辽阔的；巨大的；庞大的；大量的"}]},"collins":{"senses":[{"pos":"[ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词]","cn":"巨大的;广大的;广阔的；"}]},"examples":[{"en":"In the vast majority of cases, this should not be a problem.","cn":"在绝大多数情况下，这应该不成问题。"},{"en":"At dusk bats appear in vast numbers.","cn":"蝙蝠于傍晚时分大批出现。"}]},"vacation":{"oxford":{"phon":"vəˈkeɪʃn","pos":"noun","senses":[{"en":"(in Britain) one of the periods of time when universities or courts of law are closed; (in the US) one of the periods of time when schools, colleges, universities or courts of law are closed （","cn":"英国大学的）假期；（美国学校的）假期；（法庭的）休庭期"},{"en":"a period of time spent travelling or resting away from home","cn":"度假"}]},"collins":{"senses":[{"pos":"[N-COUNT 可数名词]","cn":"大学或美国大中小学的假期；"},{"pos":"[N-COUNT 可数名词]","cn":"假日;休假；"}]},"media":{"uk":"media/uk/vacation__gb_1.mp3","us":"media/us/vacation__us_1.mp3"},"examples":[{"en":"The job includes two weeks' paid vacation.","cn":"这份工作包括两周的带薪假期。"},{"en":"They are currently vacationing in Florida.","cn":"他们目前正在佛罗里达州度假。"}]},"vastly":{"media":{"uk":"media/uk/vastly__gb_1.mp3","us":"media/us/vastly__us_1.mp3"},"oxford":{"phon":"ˈvɑːstli","pos":"adv.","senses":[{"en":"very much","cn":"非常；很"}]},"collins":{"senses":[{"pos":"[ADV 副词]","cn":"很大程度上;极大地；"}]},"examples":[{"en":"The quality of the training has vastly improved.","cn":"训练的质量已经大幅度提高。"},{"en":"I'm a vastly different person now.","cn":"我现在已判若两人了。"}]},"valley":{"media":{"uk":"media/uk/valley__gb_1.mp3","us":"media/us/valley__us_1.mp3"},"oxford":{"phon":"ˈvæli","pos":"noun","senses":[{"en":"an area of low land between hills or mountains, often with a river flowing through it; the land that a river flows through","cn":"谷；山谷；溪谷；流域"}]},"collins":{"senses":[{"pos":"[N-COUNT 可数名词]","cn":"山谷;尤指溪谷；"}]},"examples":[{"en":"a small town set in a valley","cn":"坐落在溪谷中的小镇"},{"en":"a wooded valley","cn":"树木茂盛的山谷"}]},"various":{"media":{"uk":"media/uk/various__gb_1.mp3","us":"media/us/various__us_1.mp3"},"oxford":{"phon":"ˈveəriəs","pos":"adj.","senses":[{"en":"several different","cn":"各种不同的；各种各样的"},{"en":"( formal ) having many different features","cn":"具有多种特征的；多姿多彩的"}]},"collins":{"senses":[{"pos":"[ADJ 形容词]","cn":"各种各样的;不同种类的；"},{"pos":"[ADJ 形容词]","cn":"迥异的;千差万别的；"}]},"examples":[{"en":"She took the job for various reasons.","cn":"她由于种种原因接受了这份工作。"},{"en":"Tents come in various shapes and sizes.","cn":"帐篷有各种各样的形状和大小。"}]},"vary":{"media":{"uk":"media/uk/vary__gb_1.mp3","us":"media/us/vary__us_1.mp3"},"oxford":{"phon":"ˈveəri","pos":"verb","senses":[{"en":"to be different from each other in size, shape, etc. （","cn":"大小、形状等）相异，不同，有别"},{"en":"to change or be different according to the situation （","cn":"根据情况）变化，变更，改变"}]},"collins":{"senses":[{"pos":"[VERB 动词]","cn":"不同;有差异；"},{"pos":"[V-ERG 及物/不及物动词]","cn":"使变化;改变；"}]},"examples":[{"en":"Class numbers vary between 25 and 30.","cn":"班级的数目从 25 到 30 不等。"},{"en":"‘What time do you start work?’ ‘ It varies. ’ “","cn":"你几点钟开始工作？” “没准儿。”"}]},"variations":{"oxford":{"phon":"ˌveəriˈeɪʃn","pos":"noun","senses":[{"en":"a change, especially in the amount or level of sth （","cn":"数量、水平等的）变化，变更，变异"},{"en":"a thing that is different from other things in the same general group","cn":"变异的东西；变种；变体"}]}},"vaccine":{"oxford":{"phon":"ˈvæksiːn","pos":"noun","senses":[{"en":"a substance that is put into the blood and that protects the body from a disease","cn":"疫苗；菌苗"}]},"collins":{"senses":[{"pos":"[N-MASS 物质名词]","cn":"疫苗；"}]},"media":{"uk":"media/uk/vaccine__gb_1.mp3","us":"media/us/vaccine__us_1.mp3"},"examples":[{"en":"There is no vaccine against HIV infection.","cn":"现在还没有防止感染艾滋病病毒的疫苗。"},{"en":"a measles vaccine","cn":"麻疹疫苗"}]},"variable":{"oxford":{"phon":"ˈveəriəbl","pos":"adjective","senses":[{"en":"often changing; likely to change","cn":"多变的；易变的；变化无常的"},{"en":"able to be changed","cn":"可更改的；可变的"}]},"collins":{"senses":[{"pos":"[ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词]","cn":"多变的;易变的;反复无常的；"},{"pos":"[N-COUNT 可数名词]","cn":"质量、数量、规模等可变因素；"}]},"media":{"uk":"media/uk/variable__gb_1.mp3","us":"media/us/variable__us_1.mp3"},"examples":[{"en":"With so many variables, it is difficult to calculate the cost.","cn":"有这么多的可变因素，很难计算出成本。"},{"en":"The temperature remained constant while pressure was a variable in the experiment.","cn":"做这实验时温度保持不变，但压力可变。"}]},"vaguely":{"media":{"uk":"media/uk/vaguely__gb_1.mp3","us":"media/us/vaguely__us_1.mp3"},"oxford":{"phon":"ˈveɪɡli","pos":"adv.","senses":[{"en":"in a way that is not detailed or exact","cn":"不详细地；含糊地；不确切地"},{"en":"slightly","cn":"略微；稍微"}]},"collins":{"senses":[{"pos":"[ADV-GRADED 副词]","cn":"轻微地;有点儿；"},{"pos":"","cn":"vague"}]},"examples":[{"en":"He smiled vaguely, ignoring her questions.","cn":"他漫不经心地笑了笑，没有理会她的问题。"},{"en":"I can vaguely remember my first day at school.","cn":"我还依稀记得我第一天上学的情景。"}]},"varied":{"media":{"uk":"media/uk/varied__gb_1.mp3","us":"media/us/varied__us_1.mp3"},"oxford":{"phon":"ˈveərid","pos":"adj.","senses":[{"en":"of many different types","cn":"各种各样的；形形色色的；不相同的"},{"en":"not staying the same, but changing often","cn":"变化的；多变的；不同的"}]},"collins":{"senses":[{"pos":"[ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词]","cn":"vary"}]},"examples":[{"en":"a wide and varied selection of cheeses","cn":"种类繁多的可供选购的奶酪"},{"en":"He led a full and varied life.","cn":"他过着丰富多彩的生活。"}]},"variety":{"media":{"uk":"media/uk/variety__gb_1.mp3","us":"media/us/variety__us_1.mp3"},"oxford":{"phon":"vəˈraɪəti","pos":"noun","senses":[{"en":"several different sorts of the same thing （","cn":"同一事物的）不同种类，多种式样"},{"en":"the quality of not being the same or not doing the same thing all the time","cn":"变化；多样化；多变性"}]},"collins":{"senses":[{"pos":"[N-UNCOUNT 不可数名词]","cn":"变化;多样化；"},{"pos":"[N-SING 单数名词]","cn":"各式各样;多种多样；"}]},"examples":[{"en":"My cooking is of the ‘quick and simple’ variety.","cn":"我做饭菜属于既快捷又简单的那一类。"},{"en":"We want more variety in our work.","cn":"我们希望我们的工作多变点儿花样。"}]},"validation":{"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"if a piece of new information confirms an idea or belief that people already have, it shows that it is definitely true","cn":""},{"en":"to show that something is definitely true by providing facts","cn":""}]},"examples":[{"en":"The Supreme Court has validated the lower court’s interpretation of the law.","cn":"","src":"ld"},{"en":"Many scientists plan to wait until the results of the study are validated by future research.","cn":"","src":"ld"}],"media":{"uk":"media/uk/validation__gb_1.mp3","us":"media/us/validation__us_1.mp3"}},"variation":{"oxford":{"phon":"ˌveəriˈeɪʃn","pos":"noun","senses":[{"en":"a change, especially in the amount or level of sth （","cn":"数量、水平等的）变化，变更，变异"},{"en":"a thing that is different from other things in the same general group","cn":"变异的东西；变种；变体"}]},"collins":{"senses":[{"pos":"[N-COUNT 可数名词]","cn":"同一事物略微的变化形式；"},{"pos":"[N-VAR 可变名词]","cn":"等级或数量的变化，变动，变更；"}]},"media":{"uk":"media/uk/variation__gb_1.mp3","us":"media/us/variation__us_1.mp3"},"examples":[{"en":"This soup is a spicy variation on a traditional favourite.","cn":"这种汤是在一种受欢迎的传统汤羹中加了香料。"},{"en":"( figurative ) His numerous complaints are all variations on a theme (= all about the same thing).","cn":"他的满腹牢骚说来道去都是为了一件事。"}]},"valid":{"oxford":{"phon":"ˈvælɪd","pos":"adj.","senses":[{"en":"that is legally or officially acceptable （","cn":"法律上）有效的；（正式）认可的"},{"en":"based on what is logical or true","cn":"符合逻辑的；合理的；有根据的；确凿的"}]},"collins":{"senses":[{"pos":"[ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词]","cn":"有根据的;正当的;合理的；"},{"pos":"[ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词]","cn":"有意义的;有效的；"}]},"media":{"uk":"media/uk/valid__gb_1.mp3","us":"media/us/valid__us_1.mp3"},"examples":[{"en":"She had valid reasons for not supporting the proposals.","cn":"她有充分的理由不支持这些建议。"},{"en":"The contract had been validly drawn up.","cn":"这份合同已依据法律草拟妥当。"}]},"valuable":{"media":{"uk":"media/uk/valuable__gb_1.mp3","us":"media/us/valuable__us_1.mp3"},"oxford":{"phon":"ˈvæljuəbl","pos":"adj.","senses":[{"en":"very useful or important","cn":"很有用的；很重要的；宝贵的"},{"en":"worth a lot of money","cn":"很值钱的；贵重的"}]},"collins":{"senses":[{"pos":"[ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词]","cn":"有价值的;有益的;有用的；"},{"pos":"[ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词]","cn":"贵重的;值钱的；"}]},"examples":[{"en":"The book provides valuable information on recent trends.","cn":"此书就近来的发展趋势提供了宝贵的信息。"},{"en":"a precious Chinese vase, valued at half a million pounds","cn":"价值 50 万英镑的稀世中国花瓶"}]},"vague":{"media":{"uk":"media/uk/vague__gb_1.mp3","us":"media/us/vague__us_1.mp3"},"oxford":{"phon":"veɪɡ","pos":"adj.","senses":[{"en":"not clear in a person's mind （","cn":"思想上）不清楚的，含糊的，不明确的，模糊的"},{"en":"not having or giving enough information or details about sth","cn":"不具体的；不详细的；粗略的"}]},"collins":{"senses":[{"pos":"[ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词]","cn":"文字或言语含糊的，不明确的，不清楚的；"},{"pos":"[ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词]","cn":"记忆或想法模糊的，不清晰的；"}]},"examples":[{"en":"In the darkness they could see the vague outline of a church.","cn":"他们在黑暗中能看到一座教堂的朦胧轮廓。"},{"en":"They had only a vague idea where the place was.","cn":"他们只是大概知道那个地方的位置。"}]},"vapour":{"oxford":{"phon":"ˈveɪpə(r)","pos":"noun","senses":[{"en":"a mass of very small drops of liquid in the air, for example steam","cn":"蒸气；潮气；雾气"}]},"collins":{"senses":[{"pos":"[N-VAR 可变名词]","cn":"水汽;蒸汽;潮气；"}]},"media":{"uk":"media/uk/vapour__gb_2.mp3","us":"media/us/vapour__us_2.mp3"},"examples":[{"en":"water vapour","cn":"水蒸气"}]},"van":{"media":{"img":["media/ldoce/img/van.jpg","media/pic/trucks_comp.jpg"],"uk":"media/uk/van__gb_1.mp3","us":"media/us/van__us_1.mp3"},"oxford":{"phon":"væn","pos":"noun","senses":[{"en":"a covered vehicle with no side windows in its back half, usually smaller than a lorry/truck, used for carrying goods or people","cn":"客货车；厢式送货车"},{"en":"( NAmE ) a covered vehicle with side windows, usually smaller than a lorry/truck, that can carry about twelve passengers","cn":"面包车（通常为 12 座左右）"}]},"collins":{"senses":[{"pos":"[N-COUNT 可数名词]","cn":"厢式中小型货车;运货车；"},{"pos":"[N-COUNT 可数名词]","cn":"火车的货车车厢，邮政车厢；"}]},"examples":[{"en":"a police van (= for carrying police officers or prisoners)","cn":"警车"},{"en":"a luggage van","cn":"装运行李的车厢"}]},"value":{"media":{"uk":"media/uk/value__gb_1.mp3","us":"media/us/value__us_1.mp3"},"oxford":{"phon":"ˈvæljuː","pos":"noun","senses":[{"en":"how much sth is worth in money or other goods for which it can be exchanged （","cn":"商品）价值"},{"en":"( especially BrE ) how much sth is worth compared with its price （","cn":"与价格相比的）值，划算程度"}]},"collins":{"senses":[{"pos":"[N-UNCOUNT 不可数名词]","cn":"重要性;有用性;益处；"},{"pos":"[VERB 动词]","cn":"认为…重要;重视;珍视；"}]},"examples":[{"en":"The winner will receive a prize to the value of £1 000.","cn":"获胜者将得到价值为 1 000 英镑的奖项。"},{"en":"The young have a completely different set of values and expectations.","cn":"年轻人有一整套截然不同的价值观和期望。"}]},"validity":{"oxford":{"phon":"vəˈlɪdəti","pos":"noun","senses":[{"en":"the state of being legally or officially acceptable （","cn":"法律上的）有效，合法性；（正式的）认可"},{"en":"the state of being logical and true","cn":"符合逻辑；正当；正确"}]},"collins":{"senses":[{"pos":"[N-UNCOUNT 不可数名词]","cn":"valid"}]},"media":{"uk":"media/uk/validity__gb_1.mp3","us":"media/us/validity__us_1.mp3"},"examples":[{"en":"We had doubts about the validity of their argument.","cn":"我们对他们的论点的正确性有过怀疑。"},{"en":"The period of validity of the agreement has expired.","cn":"本协议的有效期已过。"}]},"vagina":{"oxford":{"phon":"vəˈdʒaɪnə","pos":"noun","senses":[{"en":"the passage in the body of a woman or female animal between the outer sex organs and the womb","cn":"阴道"}]},"collins":{"senses":[{"pos":"[N-COUNT 可数名词]","cn":"阴道；"}]},"media":{"uk":"media/uk/vagina__gb_1.mp3","us":"media/us/vagina__us_1.mp3"}},"valued":{"oxford":{"phon":"ˈvæljuː","pos":"noun","senses":[{"en":"how much sth is worth in money or other goods for which it can be exchanged （","cn":"商品）价值"},{"en":"( especially BrE ) how much sth is worth compared with its price （","cn":"与价格相比的）值，划算程度"}]},"media":{"uk":"media/ldoce/hwd/bre/c/brelasdevalue.mp3","us":"media/ldoce/hwd/ame/e/value1.mp3"},"examples":[{"en":"Shelley valued her privacy.","cn":""},{"en":"Mr. Yeo valued Jan for her hard work.","cn":""}]},"vantage":{"oxford":{"phon":"ˈvɑːntɪdʒ pɔɪnt","pos":"noun","senses":[{"en":"a position from which you watch sth; a point in time or a situation from which you consider sth, especially the past （","cn":"观察事物的）有利地点；（尤指考虑旧时事物的）有利时刻，有利形势"}]}},"vases":{"oxford":{"phon":"vɑːz","pos":"noun","senses":[{"en":"a container made of glass, etc., used for holding cut flowers or as a decorative object","cn":"花瓶；装饰瓶"}]}},"values":{"oxford":{"phon":"ˈvæljuː","pos":"noun","senses":[{"en":"how much sth is worth in money or other goods for which it can be exchanged （","cn":"商品）价值"},{"en":"( especially BrE ) how much sth is worth compared with its price （","cn":"与价格相比的）值，划算程度"}]}},"varies":{"oxford":{"phon":"ˈveəri","pos":"verb","senses":[{"en":"to be different from each other in size, shape, etc. （","cn":"大小、形状等）相异，不同，有别"},{"en":"to change or be different according to the situation （","cn":"根据情况）变化，变更，改变"}]}},"vaccinations":{"oxford":{"phon":"ˈvæksɪneɪt","pos":"verb","senses":[{"en":"to give a person or an animal a vaccine , especially by injecting it, in order to protect them against a disease","cn":"给 … 接种疫苗"}]}},"valleys":{"oxford":{"phon":"ˈvæli","pos":"noun","senses":[{"en":"an area of low land between hills or mountains, often with a river flowing through it; the land that a river flows through","cn":"谷；山谷；溪谷；流域"}]}},"varieties":{"oxford":{"phon":"vəˈraɪəti","pos":"noun","senses":[{"en":"several different sorts of the same thing （","cn":"同一事物的）不同种类，多种式样"},{"en":"the quality of not being the same or not doing the same thing all the time","cn":"变化；多样化；多变性"}]}},"vanished":{"oxford":{"phon":"ˈvænɪʃ","pos":"verb","senses":[{"en":"to disappear suddenly and/or in a way that you cannot explain （","cn":"莫名其妙地）突然消失"},{"en":"to stop existing","cn":"不复存在；消亡；绝迹"}]}},"vasectomy":{"collins":{"senses":[{"pos":"N-VAR","cn":"输精管切除术","en":"A vasectomy is a surgical operation in which the tube that carries sperm to a man's penis is cut, usually as a means of contraception."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a medical operation to cut the small tube through which a man’s sperm passes so that he is unable to produce children","cn":"输精管切除术"}]},"media":{"uk":"media/ldoce/hwd/bre/7/vasectomy0205.mp3","us":"media/ldoce/hwd/ame/1/vasectomy.mp3"}},"variegated":{"collins":{"senses":[{"pos":"ADJ","cn":"（树叶或植物）杂色的，斑驳的","en":"A variegated leaf or plant has different colours on it. 【搭配模式】：usu ADJ n 【FIELD标签】：TECHNICAL 术语 The leaves are a red. 这些树叶呈斑驳的红色。"},{"pos":"ADJ-GRADED","cn":"多种多样的;形形色色的","en":"Something that is variegated consists of many different parts or types. 【语域标签】：FORMAL 正式 ...our dialects. 我们形形色色的方言"}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a variegated plant, leaf etc has different coloured marks on it 〔","cn":"植物﹑叶子等〕杂色的﹐斑驳的"},{"en":"consisting of a lot of different types of thing","cn":"多样化的﹐形形色色的"}]},"vocab":{"pos":"adj","senses":[{"en":"Something variegated has many different colors, as in the trees of autumn or the feathers of a peacock. Whenever you see \"vari\" at the beginning of a word, you know that the idea of difference or change is involved."}]},"media":{"uk":"media/ldoce/hwd/bre/4/ld41variegated.mp3","us":"media/ldoce/hwd/ame/8/variegated.mp3"},"examples":[{"en":"a plant with variegated leaves","cn":"斑叶植物"},{"en":"variegated grasses","cn":"杂色的草"}]},"vatican":{"collins":{"senses":[{"pos":"N-PROPER","cn":"梵蒂冈;天主教教皇（或教廷）","en":"The Vatican is the city state in Rome ruled by the Pope which is the centre of the Roman Catholic Church. You can also use the Vatican to refer to the Pope or his officials. 【搭配模式】： the N The president had an audience with the Pope in the ."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the large palace in Rome where the Pope (= head of the Roman Catholic Church ) lives and works","cn":"梵蒂冈〔罗马教皇的宫廷〕"},{"en":"the government of the Pope","cn":"梵蒂冈〔指罗马教廷〕"}]},"media":{"uk":"media/ldoce/hwd/bre/3/ld41vatican.mp3","us":"media/ldoce/hwd/ame/d/vatican.mp3"},"examples":[{"en":"The Vatican is taking a hard line on birth control.","cn":"梵蒂冈在节育的问题上立场强硬。"}]},"valiant":{"collins":{"senses":[{"pos":"ADJ-GRADED","cn":"勇敢的;果决的;无畏的","en":"A valiant action is very brave and determined, though it may lead to failure or defeat. 【搭配模式】：usu ADJ n Despite efforts by the finance minister, inflation rose to 36%. 尽管财政部部长采取了一系列果决措施，通货膨胀率还是涨到了36%。 ...a attempt to keep the business goin"}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"very brave, especially in a difficult situation 〔","cn":"尤指在困境中〕勇敢的﹐英勇的"}]},"vocab":{"pos":"adj","senses":[{"en":"It was pretty courageous of the automaker Plymouth to name a car the \"Valiant\" in the 1960s and 70s because that term usually refers to a hero or describes a really determined, or valiant, effort that doesn't end well."}]},"media":{"uk":"media/ldoce/hwd/bre/c/valiant0205.mp3","us":"media/ldoce/hwd/ame/4/valiant.mp3"},"examples":[{"en":"She made a valiant attempt not to laugh.","cn":"她试图强忍住不笑出来。"},{"en":"valiant warriors","cn":"勇敢的武士"}]},"vaporize":{"collins":{"senses":[{"pos":"V-ERG","cn":"（使）汽化;（使）蒸发","en":"If a liquid or solid vaporizes or if you vaporize it, it changes into vapour or gas. 【语法信息】：V 【语法信息】：V n The benzene d and formed a huge cloud of gas... 苯蒸发了,形成了一大团气体。 The blast may have vaporised the meteorite. 爆炸可能使陨石气化了。"}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to change into a vapour, or to make something, especially a liquid, do this (","cn":"使)蒸发﹐(使)汽化"}]},"vocab":{"pos":"v","senses":[{"en":"To vaporize is to evaporate and turn into gas. If you're watching a sci-fi movie, it probably means to vanish quickly or be utterly obliterated by a phaser gun."}]},"media":{"uk":"media/ldoce/hwd/bre/6/vaporize0205.mp3","us":"media/ldoce/hwd/ame/e/vaporize.mp3"}},"vaccinate":{"collins":{"senses":[{"pos":"VERB","cn":"给…接种疫苗","en":"If a person or animal is vaccinated , they are given a vaccine, usually by injection, to prevent them from getting a disease. 【语法信息】： be V-ed against n 【语法信息】： have n V-ed against n 【语法信息】： be/get V-ed 【搭配模式】：usu passive Dogs must be d agai"}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to protect a person or animal from a disease by giving them a vaccine","cn":"给…接种疫苗﹐给…打预防针"}]},"vocab":{"pos":"v","senses":[{"en":"To vacciunate is to immunize someone against a disease. Babies are usually vaccinated against many diseases soon after birth."}]},"media":{"uk":"media/ldoce/hwd/bre/6/ld41vaccinate.mp3","us":"media/ldoce/hwd/ame/b/vaccinate.mp3"},"examples":[{"en":"Make sure your vaccinations are up to date.","cn":"一定要接种最新的疫苗。"},{"en":"I was vaccinated against tetanus.","cn":"我接种了破伤风疫苗。"}]},"vandalise":{"collins":{"senses":[{"pos":"","cn":"","en":"→see: ;"}]}},"vacuity":{"collins":{"senses":[{"pos":"N-UNCOUNT","cn":"(思想的)贫乏,空洞,空虚","en":"If you refer to the vacuity of something or someone, you are critical of them because they lack intelligent thought or ideas. 【搭配模式】：usu with poss 【语用信息】：disapproval 【语域标签】：FORMAL 正式 His was a handicap in these debates. 在这些辩论中，思想贫乏是他的一个弱点。 "}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"lack of intelligent, interesting, or serious thought","cn":"愚蠢﹔空虚﹔贫乏"}]},"vocab":{"pos":"n","senses":[{"en":"When you refer to something that is not there, you can refer to its vacuity . A stern teacher who is criticizing an empty-headed English essay might talk about its vacuity , or the absence of any real substance."}]},"media":{"uk":"media/ldoce/hwd/bre/0/ld41vacuity.mp3","us":"media/ldoce/hwd/ame/f/vacuity.mp3"}},"varsity":{"collins":{"senses":[{"pos":"ADJ","cn":"（尤用于修饰体育活动或体育比赛代表队）大学的","en":"People sometimes use varsity to describe things that relate to universities, especially sports activities or teams at a university or competitions between universities. 【搭配模式】：ADJ n 【语域标签】：BRIT 英 【FIELD标签】：mainly JOURNALISM 主新闻 The school h"},{"pos":"N-COUNT","cn":"（学校的）校队，代表队","en":"The varsity is the main or first team for a particular sport at a high school, college, or university. 【搭配模式】：oft N n 【语域标签】：AM 美 She has been in the playoffs every year since she made the ... 自从加入校队后，她每年都能参加季后赛。 Shaun McCalister also playe"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the main team that represents a university, college, or school in a sport 〔","cn":"体育比赛中的〕学校代表队﹐校队"},{"en":"a university, especially Oxford or Cambridge","cn":"大学〔尤指牛津大学或剑桥大学〕"}]},"vocab":{"pos":"n","senses":[{"en":"The word varsity identifies the starting team in a sport at a college or university. You have to be good to make varsity ."}]},"media":{"uk":"media/ldoce/hwd/bre/4/ld41varsity.mp3","us":"media/ldoce/hwd/ame/a/varsity.mp3"},"examples":[{"en":"She's still at varsity.","cn":"她还在上大学。"},{"en":"the varsity match","cn":"大学体育比赛"}]},"vac":{"collins":{"senses":[{"pos":"N-COUNT","cn":"（大学的）假期，寒暑假","en":"A vac is a period of the year when universities and colleges are officially closed. Vac is an abbreviation for (缩略=) 'vacation'. 【搭配模式】：usu sing 【语域标签】：BRIT 英 【语域标签】：INFORMAL 非正式 ...the summer . 暑假"},{"pos":"N-COUNT","cn":"真空吸尘器","en":"A vac is an electric machine which sucks up dust and dirt from carpets. Vac is an abbreviation for (缩略=) 'vacuum cleaner'. 【语域标签】：INFORMAL 非正式 We found the easy to push. 我们发现这种真空吸尘器很容易推着走。"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a university vacation 1 (3) 〔","cn":"大学的〕假期"}]},"media":{"uk":"media/ldoce/hwd/bre/9/ld41vac.mp3","us":"media/ldoce/hwd/ame/2/laadvac.mp3"}},"valueless":{"collins":{"senses":[{"pos":"ADJ","cn":"无价值的;无用的;无效的","en":"If you describe something as valueless , you mean that it is not at all useful. Such attitudes are unless they reflect inner cognition and certainty. 这种态度如果不能反映内心的认知和把握就毫无价值。 ...commercially trees. 毫无商业价值的树木"}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"worth no money or very little money","cn":"不值钱的"},{"en":"having no worth, importance, or good qualities","cn":"没有价值的﹔不重要的﹔质量差的"}]},"collocations":{"phrases":["VERBS be, seem | become","ADV. completely, quite Our shares became completely valueless overnight.","PREP. as Some of the royal forests had become valueless as hunting grounds."]},"media":{"uk":"media/ldoce/hwd/bre/2/ld41valueless.mp3","us":"media/ldoce/hwd/ame/5/laadvalueless.mp3"},"examples":[{"en":"On most political issues my own opinion was pretty well valueless.","cn":"在大多数政治问题上﹐我个人的观点很不重要。"},{"en":"valueless currency","cn":"不值钱的货币"}]},"vapid":{"collins":{"senses":[{"pos":"ADJ-GRADED","cn":"乏味的;枯燥的;无趣的","en":"If you describe someone or something as vapid , you are critical of them because they are dull and uninteresting. 【语用信息】：disapproval ...the Minister's young and rather wife... 部长年轻无趣的妻子 She made a comment about the weather. 她对天气作了一番平淡无奇的评论。"}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"lacking intelligence, interest, or imagination","cn":"缺少灵性的﹔乏味的﹔平庸的"}]},"vocab":{"pos":"adj","senses":[{"en":"Reserve the adjective vapid for the airhead in your office that brings nothing to the table, except maybe the doughnuts. Vapid is an adjective to describe someone or something that is dull or uninspiring."}]},"media":{"uk":"media/ldoce/hwd/bre/7/ld41vapid.mp3","us":"media/ldoce/hwd/ame/1/vapid.mp3"},"examples":[{"en":"vapid conversation","cn":"平淡乏味的对话"}]},"vanilla":{"collins":{"senses":[{"pos":"N-UNCOUNT","cn":"香草精;香子兰精","en":"Vanilla is a flavouring used in ice cream and other sweet food. 【搭配模式】：usu N n I added a dollop of ice-cream to the pie. 我在馅饼里加了一块香草冰激凌。 ... essence. 香草精"},{"pos":"ADJ","cn":"寻常的;无特色的","en":"If you describe a person or thing as vanilla , you mean that they are ordinary, with no special or extra features. ...just plain couples like me and Tony... 只是如我和托尼一样的平常夫妇 The tensions of the Nixon presidency were replaced by the plain admi"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a substance used to give a special taste to ice cream , cakes etc, made from the beans of a tropical plant","cn":"香草精﹐香子兰精"},{"en":"having the taste of vanilla","cn":"香草味的"},{"en":"plain, ordinary, or uninteresting","cn":"寻常的﹐无特色的﹐乏味的"}]},"vocab":{"pos":"n adj","senses":[{"en":"Vanilla is the flavor for food — such as ice cream — that contains extract from the vanilla plant. This word also describes things that are boring or plain."}]},"media":{"uk":"media/ldoce/hwd/bre/a/vanilla_adj0205.mp3","us":"media/ldoce/hwd/ame/c/vanilla1.mp3"},"examples":[{"en":"The city is pretty much plain vanilla.","cn":"这座城市相当一般化。"},{"en":"( BrE ) a vanilla pod","cn":"香子兰蒴果"}]},"vapor":{"collins":{"senses":[{"pos":"","cn":"","en":"→see: ;"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the American spelling of vapour vapour","cn":"的美式拼法"}]},"vocab":{"pos":"n","senses":[{"en":"When something that is normally liquid — like water — becomes a visible, gas-like substance floating in the air, it's a vapor ."}]},"media":{"uk":"media/ldoce/hwd/bre/7/ld41vapor.mp3","us":"media/ldoce/hwd/ame/4/vapor.mp3"}},"vainglorious":{"collins":{"senses":[{"pos":"ADJ","cn":"非常自负的;自命不凡的","en":"If you describe someone as vainglorious , you are critical of them because they are very proud of what they have done and boast a lot about it. 【搭配模式】：ADJ n 【语用信息】：disapproval 【STYLE标签】：LITERARY 文"}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"too proud of your own abilities, importance etc","cn":"非常自负的﹐自命不凡的"}]},"vocab":{"pos":"adj","senses":[{"en":"If you admire yourself in the mirror all the time and constantly brag about all the beauty contests you have won, you might rightfully get accused of being vainglorious ."}]},"media":{"uk":"media/ldoce/hwd/bre/f/vainglorious0205.mp3","us":"media/ldoce/hwd/ame/f/laadvainglorious.mp3"}},"vat":{"collins":{"senses":[{"pos":"N-UNCOUNT","cn":"增值税","en":"VAT is a tax that is added to the price of goods or services. VAT is an abbreviation for (缩略=) 'value added tax'. 【语域标签】：BRIT 英"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a very large container for storing liquids in 〔","cn":"储存液体用的〕大缸﹐大桶﹐罐"}]},"vocab":{"pos":"n","senses":[{"en":"A vat is a big container for holding liquids. If you're having a big party, your mom may get you to help cook a vat of spaghetti sauce to feed all your hungry relatives."}]},"media":{"uk":"media/ldoce/hwd/bre/d/vat0703.mp3","us":"media/ldoce/hwd/ame/d/vat0703.mp3"},"examples":[{"en":"Prices include VAT.","cn":"价格中含增值税。"},{"en":"£27.50 + VAT * 27.50","cn":"英镑加增值税"}]},"valedictory":{"collins":{"senses":[{"pos":"ADJ","cn":"（致词、书信或演出）告别的，告别性质的","en":"A valedictory speech, letter, or performance is one that is intended as a way of saying goodbye when someone leaves another person, a place, or a job. 【搭配模式】：usu ADJ n 【语域标签】：FORMAL 正式 ...Mr Walker, making his address after two years as cha"},{"pos":"N-COUNT","cn":"（优秀生在毕业典礼上作的）告别演说","en":"A valedictory is a speech that is given by the student with the highest marks in their class at their graduation ceremony. 【搭配模式】：oft N n 【语域标签】：AM 美 He listened to Howard give the address at high school graduation. 他听了霍华德在中学毕业典礼上作的告别演讲。"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a speech or statement in which you say goodbye when you are leaving a school, job etc, especially on a formal occasion 〔","cn":"尤指在正式场合上的〕告别辞"}]},"vocab":{"pos":"n adj","senses":[{"en":"A valedictory is a speech expressing farewell, as at a school graduation. The adjective valedictory relates to saying good-bye, but almost always refers to a speech or address."}]},"media":{"uk":"media/ldoce/hwd/bre/3/ld41valedictory.mp3","us":"media/ldoce/hwd/ame/e/valedictory.mp3"},"examples":[{"en":"a valedictory speech","cn":"告别演说"}]},"valuer":{"collins":{"senses":[{"pos":"N-COUNT","cn":"评估师;鉴定人;估价员","en":"A valuer is someone whose job is to estimate the cost or value of something, for example a house, or objects that are going to be sold in an auction. 【语域标签】：BRIT 英"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone whose job is to decide how much money something is worth","cn":"估价者"}]},"media":{"uk":"media/ldoce/hwd/bre/a/ld41valuer.mp3","us":"media/ldoce/hwd/ame/a/ld41valuer.mp3"}},"validate":{"collins":{"senses":[{"pos":"VERB","cn":"证实;确证;确认","en":"To validate something such as a claim or statement means to prove or confirm that it is true or correct. 【语法信息】：V n 【语域标签】：FORMAL 正式 This discovery seems to the claims of popular astrology. 这个发现似乎能印证流行占星术的一些说法。 ...how that evidence was eval"},{"pos":"VERB","cn":"证明…有价值;认可","en":"To validate a person, state, or system means to prove or confirm that they are valuable or worthwhile. 【语法信息】：V n She is looking for an image that s her... 她在寻求一种能够证明自己价值的形象。 The Academy Awards appear to his career. 奥斯卡金像奖似乎是对他事业的肯定。"}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"if a piece of new information confirms an idea or belief that people already have, it shows that it is definitely true","cn":""},{"en":"to show that something is definitely true by providing facts","cn":""},{"en":"to provide additional information to help prove that a statement, belief, or explanation is correct","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"To validate is to prove that something is based on truth or fact, or is acceptable. It can also mean to make something, like a contract, legal."}]},"media":{"uk":"media/ldoce/hwd/bre/e/validate0205.mp3","us":"media/ldoce/hwd/ame/3/validate.mp3"},"examples":[{"en":"Check that their courses have been validated by a reputable organization.","cn":"要确保他们的课程获得有声望机构的承认。"},{"en":"to validate a contract","cn":"使合同生效"}]},"vaseline":{"collins":{"senses":[{"pos":"N-UNCOUNT","cn":"凡士林;矿脂","en":"Vaseline is a soft clear jelly made from petroleum, which is used to protect the skin and for other purposes. TRADEMARK 商标"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a soft clear substance used on the skin for various medical and other purposes","cn":"凡士林"}]},"media":{"uk":"media/ldoce/hwd/bre/8/vaseline0205.mp3","us":"media/ldoce/hwd/ame/1/vaseline.mp3"}},"vanity":{"collins":{"senses":[{"pos":"N-UNCOUNT","cn":"虚荣(心);自负","en":"If you refer to someone's vanity , you are critical of them because they take great pride in their appearance or abilities. 【搭配模式】：also N in pl 【语用信息】：disapproval Men who use steroids are motivated by sheer ... 使用类固醇的男人纯粹是受虚荣心的驱使。 With my u"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an unreasonable pride in your own abilities or qualities, which makes you behave rudely, as if other people were of no importance or interest","cn":""},{"en":"too much pride in your own abilities, appearance, or qualities, especially following a success which has made you behave as if you are very important","cn":""},{"en":"great pride in yourself so that you are always thinking about yourself, especially about your appearance","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Vanity is the quality of being vain , or having a ridiculous amount of pride. If you have excessive vanity in your appearance, you probably spend long hours sitting at your vanity table doing your makeup or plucking your nose hairs."}]},"collocations":{"phrases":["ADJ. great | female, human, male, personal","VERB + VANITY appeal to, flatter My suggestion appealed to her vanity."]},"media":{"uk":"media/ldoce/hwd/bre/1/vanity0205.mp3","us":"media/ldoce/hwd/ame/1/vanity.mp3"},"examples":[{"en":"Politics is too often concerned only with the personal vanities of politicians.","cn":"政治常常仅与政界人士的个人虚荣有关。"},{"en":"the vanity of human ambition in the face of death","cn":"个人抱负在死亡面前的微不足道"}]},"vanish":{"collins":{"senses":[{"pos":"VERB","cn":"消失;失踪;突然不见","en":"If someone or something vanishes , they disappear suddenly or in a way that cannot be explained. 【语法信息】：V 【语法信息】：V from n 【语法信息】：V into n He just ed and was never seen again... 他就这么消失了，再也没人见到过他。 The aircraft ed without trace... 飞机消失得无影无踪。 A"},{"pos":"VERB","cn":"(物种）灭绝;（传统）消亡","en":"If something such as a species of animal or a tradition vanishes , it stops existing. 【语法信息】：V 【语法信息】：V from n Near the end of Devonian times, thirty percent of all animal life ed... 在泥盆纪末期，30％的动物物种都灭绝了。 ...all the species of birds that had"}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"if something disappears, you cannot see it any longer, or it does not exist any longer","cn":""},{"en":"to completely disappear, especially suddenly","cn":""},{"en":"to stop existing – used about something bad such as a pain or a problem","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"A car driving into the distance, a member of a near-extinct species, or that last piece of pecan pie in the refrigerator — any of these things is likely to vanish soon, meaning \"to disappear.\""}]},"collocations":{"phrases":["ADV. just, simply I turned round and she had simply vanished. | abruptly, instantly, promptly, suddenly | quickly, rapidly Her feelings of s","VERB + VANISH seem to | make sb/sth","PREP. from All thoughts of romance vanished from his mind. | into She vanished into the mist.","PHRASES vanish from the face of the earth, vanish from sight, vanish into thin air At a stroke she could make things vanish into thin air. |","ADV. altogether, completely, entirely, totally Many of these old cinemas have now vanished altogether. | all but, almost, virtually country ","PREP. from This plant is vanishing from the British countryside."]},"media":{"uk":"media/ldoce/hwd/bre/3/brelasdevanish.mp3","us":"media/ldoce/hwd/ame/9/vanish.mp3"},"examples":[{"en":"All hopes of a peaceful settlement had now vanished.","cn":"和平解决的全部希望现已化为泡影。"},{"en":"The magician vanished in a puff of smoke.","cn":"魔术师在一股烟雾中突然不见了。"}]},"vandalism":{"collins":{"senses":[{"pos":"N-UNCOUNT","cn":"（尤指对公共财产的）故意破坏，捣毁","en":"Vandalism is the deliberate damaging of things, especially public property. ...acts of . 故意破坏公共财产的行为 ...a 13-year-old boy whose crime file includes violence, theft, and bullying. 集暴力犯罪、偷窃、故意破坏公共财产和流氓行径等罪行于一身的13岁男孩"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the crime of deliberately setting fire to a building","cn":""},{"en":"the crime of deliberately damaging things, especially public property","cn":"破坏财物（罪）〔尤指破坏公共财物〕"},{"en":"the crime of deliberately damaging things, especially public property","cn":"破坏财物（罪）〔尤指破坏公共财物〕"}]},"vocab":{"pos":"n","senses":[{"en":"Vandalism is the destruction of someone else's property. Some people think of graffiti as public art, while others dismiss it as nothing but vandalism ."}]},"collocations":{"phrases":["ADJ. mindless, wanton | criminal | environmental","VERB + VANDALISM discourage, prevent","PHRASES an act of vandalism"]},"media":{"uk":"media/ldoce/hwd/bre/c/vandalism0205.mp3","us":"media/ldoce/hwd/ame/5/vandalism.mp3"},"examples":[{"en":"an act of vandalism","cn":"恣意破坏公共财物的行为"}]},"vacationer":{"collins":{"senses":[{"pos":"N-COUNT","cn":"（在某地）度假的人，度假者","en":"Vacationers are people who are on vacation in a particular place. 【搭配模式】：usu pl 【语域标签】：mainly AM 主美"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who has gone somewhere for a holiday","cn":"度假者"}]},"media":{"uk":"media/ldoce/hwd/bre/c/vacationer0205.mp3","us":"media/ldoce/hwd/ame/2/vacationer.mp3"}},"vandalize":{"collins":{"senses":[{"pos":"VERB","cn":"故意破坏;肆意捣毁","en":"If something such as a building or part of a building is vandalized by someone, it is damaged on purpose. 【语法信息】： be V-ed 【语法信息】：V n The walls had been horribly d with spray paint... 墙壁被用喷漆喷得一塌糊涂。 About 1,000 rioters d buildings and looted "}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to cause physical harm to something or someone, or have a bad effect on them","cn":""},{"en":"to have a bad effect on something","cn":""},{"en":"to have a bad effect on something and make it less successful, enjoyable, useful etc","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/c/vandalize0205.mp3","us":"media/ldoce/hwd/ame/7/laadvandalize.mp3"},"examples":[{"en":"The cemetery was vandalized during the night.","cn":"公墓在夜间遭到了破坏。"}]},"vampire":{"collins":{"senses":[{"pos":"N-COUNT","cn":"（传说和恐怖故事中在夜间离开坟墓吸食活人血的）吸血鬼","en":"A vampire is a creature in legends and horror stories. Vampires are said to come out of graves at night and suck the blood of living people."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"in stories, a dead person that sucks people’s blood by biting their necks","cn":"吸血鬼"}]},"vocab":{"pos":"n","senses":[{"en":"Although traditionally used to refer to the bloodsucking undead, you can use the noun vampire to describe someone who heartlessly preys on others — a blackmailer, or anyone else who just sucks the life out of you."}]},"media":{"uk":"media/ldoce/hwd/bre/8/vampire0205.mp3","us":"media/ldoce/hwd/ame/4/vampire.mp3"}},"valance":{"collins":{"senses":[{"pos":"N-COUNT","cn":"（装饰床沿的）挂布，挂帘，短帷幔","en":"A valance is a piece of cloth that hangs down over the sides of a bed in order to make it look nice."},{"pos":"N-COUNT","cn":"（窗户顶部的）木框，短帷幔","en":"A valance is a long narrow piece of wood or fabric which is fitted at the top of a window for decoration and to hide the curtain rail. 【语域标签】：AM 美"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a narrow piece of cloth that hangs from the edge of a shelf or from the frame of a bed to the floor 〔","cn":"挂在架子边缘﹑床沿等的〕挂帘﹐短帷幔﹐挂布"},{"en":"a narrow piece of cloth above a window, covering the rail the curtains hang on 〔","cn":"窗帘上端的〕布帷幔"}]},"media":{"uk":"media/ldoce/hwd/bre/8/ld41valance.mp3","us":"media/ldoce/hwd/ame/0/valance.mp3"}},"vagrant":{"collins":{"senses":[{"pos":"N-COUNT","cn":"流浪汉;漂泊者;乞丐","en":"A vagrant is someone who moves a lot from place to place because they have no permanent home or job, and have to ask for or steal things in order to live. He lived on the street as a . 他以在大街上乞讨为生。"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who has no home or regular work","cn":""},{"en":"a person, usually a man, who has no home or regular job and asks people for money on the streets","cn":""},{"en":"a woman with no home or job who carries all her possessions around with her in a bag","cn":""}]},"vocab":{"pos":"n adj","senses":[{"en":"A vagrant is someone who is homeless and poor and may wander from place to place. In fiction a vagrant often is a criminal, but a real-life vagrant might just be a person who has lost a job and family and lives off the streets with help from charity."}]},"media":{"uk":"media/ldoce/hwd/bre/1/vagrant0205.mp3","us":"media/ldoce/hwd/ame/a/vagrant.mp3"}},"vascular":{"collins":{"senses":[{"pos":"ADJ","cn":"血管的;(动物)脉管的;(植物)维管的","en":"Vascular is used to describe the channels and veins through which fluids pass in the bodies of animals and plants. 【搭配模式】：ADJ n 【FIELD标签】：TECHNICAL 术语 ...the oldest known plants. 已知的最古老的维管植物 ... diseases of the legs. 腿部血管病"}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"relating to the tubes through which liquids flow in the bodies of animals or in plants 〔","cn":"动物〕脉管的﹔〔植物〕维管的"}]},"vocab":{"pos":"adj","senses":[{"en":"Use the adjective vascular when you're talking about blood vessels. One side effect of long-term smoking is vascular disease."}]},"media":{"uk":"media/ldoce/hwd/bre/a/vascular0205.mp3","us":"media/ldoce/hwd/ame/5/vascular.mp3"},"examples":[{"en":"vascular disease","cn":"脉管疾病"}]},"vacuum":{"collins":{"senses":[{"pos":"N-COUNT","cn":"空位;空缺;空白","en":"If someone or something creates a vacuum , they leave a place or position which then needs to be filled by another person or thing. 【搭配模式】：usu sing The collapse of the army left a in the area... 这支军队的溃败使这个地区出现了军事真空。 His presence should fill"},{"pos":"PHRASE","cn":"在封闭状态中;与外界隔绝","en":"If something is done in a vacuum , it is not affected by any outside influences or information. 【搭配模式】：PHR after v Moral values cannot be taught in a ... 道德价值观的教育不能脱离实际。 We lived in a — no life, no news, no books. 我们生活在与世隔绝的环境里——没有其他生物，收不到外"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a space that is completely empty of all gas, especially one from which all the air has been taken away","cn":"真空"},{"en":"a vacuum cleaner","cn":"真空吸尘器"},{"en":"a situation in which someone or something is missing or lacking","cn":"空白﹔空虚"}]},"vocab":{"pos":"n v","senses":[{"en":"A vacuum is essentially a great lack of something — a place where virtually all matter, even air, has been removed. It can describe something that's literally empty — or something that just seems that way, like a political vacuum."}]},"collocations":{"phrases":["ADJ. perfect | moral, political, spiritual The writer criticized the moral vacuum in society. | power Her resignation left a power vacuum in","VERB + VACUUM create, leave, produce The machine then creates a vacuum. | fill Other gases rush in to fill the vacuum."]},"media":{"uk":"media/ldoce/hwd/bre/3/vacuum_las2_br.mp3","us":"media/ldoce/hwd/ame/d/vacuum1.mp3"},"examples":[{"en":"His resignation has created a vacuum which cannot easily be filled.","cn":"他的引退造成了难以填补的空白。"},{"en":"to give a room a quick vacuum","cn":"用吸尘器把房间迅速清扫一下"}]},"valour":{"collins":{"senses":[{"pos":"N-UNCOUNT","cn":"（尤指战争中的)英勇表现，勇气，勇猛","en":"Valour is great bravery, especially in battle. discretion is the better part of valour →see: ; 【STYLE标签】：LITERARY 文 He was himself decorated for in the war. 他自己因在战争中的英勇表现而获得了勋章。"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"great courage, especially in war 〔","cn":"尤指在战争中的〕勇猛﹐勇武"}]},"collocations":{"phrases":["ADJ. great a soldier famed for his great valour","VERB + VALOUR demonstrate, display, show He showed valour and skill on the battlefield.","PREP. an act/a deed of valour"]},"media":{"uk":"media/ldoce/hwd/bre/0/valour0205.mp3","us":"media/ldoce/hwd/ame/b/valor.mp3"},"examples":[{"en":"medals awarded for valor","cn":"表彰英勇的勋章"},{"en":"deeds of valour","cn":"英勇事迹"}]},"variability":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"feelings or conditions that are changeable change frequently so that it is difficult to know what they will be like in a short time","cn":""},{"en":"behaviour, processes, or services that are erratic change suddenly in an unexpected and surprising way, when it would be better if they remained the same","cn":""},{"en":"a volatile situation or character is likely to change suddenly and unexpectedly","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"The weather in San Francisco is known for its variability . One minute it's summer and the next, winter. Variability means the tendency to shift or change — of being \"variable.\""}]},"collocations":{"phrases":["ADJ. considerable, extreme, great, high, wide There is considerable variability in all the test scores. | low, slight","QUANT. degree","PREP. ~ among/between variability among different health authorities | ~ in variability in crop yields"]},"media":{"uk":"media/ldoce/hwd/bre/6/variable_adj0205.mp3","us":"media/ldoce/hwd/ame/2/l3variable.mp3"},"examples":[{"en":"a degree of variability in the exchange rate","cn":"汇率的变化幅度"},{"en":"climatic variability","cn":"气候的多变性"}]},"vault":{"collins":{"senses":[{"pos":"N-COUNT","cn":"金库;保险库","en":"A vault is a secure room where money and other valuable things can be kept safely. Most of the money was in storage in bank s... 大部分钱都存放在银行的保险库里。 The gold recovered so far is being held in a at a secret location. 到目前为止，找回来的金子都保存在一个秘密地点的金库中。"},{"pos":"N-COUNT","cn":"（通常指安葬同一家族死者的）教堂地下室，墓穴,墓室","en":"A vault is a room underneath a church or in a cemetery where people are buried, usually the members of a single family. He ordered that Matilda's body should be buried in the family . 他指示马蒂尔达的遗体必须葬在家族墓穴里。"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a room with thick walls and a strong door where money, jewels etc are kept to prevent them from being stolen or damaged 〔","cn":"贵重财物的〕保管库﹐保险库﹔金库"},{"en":"a room where people from the same family are buried, often under the floor of a church 〔","cn":"常指教堂地下某一家族的〕墓穴﹐墓室"},{"en":"a jump over something","cn":"跳跃﹐腾跃"}]},"vocab":{"pos":"n v","senses":[{"en":"Vault is a verb that means \"to jump over something.\" If you were hurrying out to the pasture to visit your favorite cow, you might vault over the gate in your excitement."}]},"collocations":{"phrases":["ADJ. secure | bank, museum | treasure","VERB + VAULT keep/store sth in","PREP. in a/the ~ The jewels were kept in a bank vault. 2 room under a church where dead people are buried","ADJ. burial, family, royal","VERB + VAULT bury sb in She is to be buried in the family vault."]},"media":{"uk":"media/ldoce/hwd/bre/1/vault_v0205.mp3","us":"media/ldoce/hwd/ame/2/vault1.mp3"},"examples":[{"en":"She vaulted over the gate and ran up the path.","cn":"她用手一撑跃过栅栏门沿着小路跑去。"},{"en":"to vault a fence","cn":"跃过篱笆墙"}]},"vagrancy":{"collins":{"senses":[{"pos":"N-UNCOUNT","cn":"流浪;漂泊","en":"Vagrancy is a way of life in which someone moves a lot from place to place because they have no permanent home or job, and have to ask for or steal things in order to live. Vagrancy and begging has become commonplace in London. 流浪和乞讨在伦敦已变得很"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the criminal offence of living on the street and begging ( beg ) from people","cn":"流浪罪"}]},"media":{"uk":"media/ldoce/hwd/bre/b/ld41vagrancy.mp3","us":"media/ldoce/hwd/ame/b/vagrancy.mp3"}},"valentine":{"collins":{"senses":[{"pos":"N-COUNT","cn":"情人节贺卡","en":"A valentine or a valentine card is a greetings card that you send to someone who you are in love with or are attracted to, usually without signing your name, on St Valentine's Day, the 14th of February."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone you love or think is attractive, that you send a card to on St Valentine’s Day 〔","cn":"在圣瓦伦丁节(2月14日)向其赠送贺卡的〕情人"},{"en":"a card you send to someone on St Valentine’s Day","cn":"圣瓦伦丁节贺卡﹐情人卡"}]},"vocab":{"pos":"n","senses":[{"en":"A valentine is a sweetheart: specifically, someone who receives a greeting or attention on Valentine's Day."}]},"media":{"uk":"media/ldoce/hwd/bre/0/brelasdevalentine.mp3","us":"media/ldoce/hwd/ame/3/amelasdevalentine.mp3"},"examples":[{"en":"Be my valentine.","cn":"做我的情人吧。"}]},"vamp":{"collins":{"senses":[{"pos":"N-COUNT","cn":"（利用色相勾引男人的）荡妇，妖妇，女骗子","en":"If you describe a woman as a vamp , you mean that she uses her sexual attractiveness to get what she wants from men. 【语用信息】：disapproval"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a woman who uses her sexual attractiveness to make men do what she wants 〔","cn":"利用色相勾引并利用男子的〕妖妇﹐荡妇"}]},"vocab":{"pos":"1 n v 2 n v 3 n 4 v","senses":[{"en":"A vamp is an attractive, dangerously flirtatious woman. A vamp in an old movie might wear tight clothes and bright red lipstick."}]},"media":{"uk":"media/ldoce/hwd/bre/9/ld41vamp.mp3","us":"media/ldoce/hwd/ame/f/vamp.mp3"}},"vacuous":{"collins":{"senses":[{"pos":"ADJ-GRADED","cn":"思想贫乏的;空洞的;无知的","en":"If you describe a person or their comments as vacuous , you are critical of them because they lack intelligent thought or ideas. 【语用信息】：disapproval Male models are not always so as they are made out to be. 男模特儿并不总像人们说的那样愚蠢。 ...the usual com"}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"showing no intelligence or having no useful purpose","cn":"无知的﹔空洞的﹔没有意义的"}]},"vocab":{"pos":"adj","senses":[{"en":"Reserved for the harmlessly stupid and truly meaningless, vacuous is a smart-sounding way to describe something dumb. Celebrity gossip and reality TV is usually pretty vacuous , even if it's fun."}]},"media":{"uk":"media/ldoce/hwd/bre/6/ld41vacuous.mp3","us":"media/ldoce/hwd/ame/9/vacuous.mp3"},"examples":[{"en":"a vacuous expression","cn":"茫然的表情"},{"en":"a vacuous romantic novel","cn":"空洞的爱情小说"}]},"vanquish":{"collins":{"senses":[{"pos":"VERB","cn":"（彻底）征服，击败，战胜","en":"To vanquish someone means to defeat them completely in a battle or a competition. 【语法信息】：V n 【STYLE标签】：LITERARY 文 A happy ending is only possible because the hero has first ed the dragons... 只有主人公先把那些恶龙制服，才有可能实现大团圆结局。 With knowledge and wis"}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to defeat someone or something completely","cn":"彻底征服﹐彻底击败"}]},"vocab":{"pos":"v","senses":[{"en":"To vanquish is to be the complete and total winner, to overpower and overcome, whether in a contest, a race, or a war. It generally suggests a total trouncing, to the point of humiliation — or worse — for the loser."}]},"media":{"uk":"media/ldoce/hwd/bre/a/vanquish0205.mp3","us":"media/ldoce/hwd/ame/0/vanquish.mp3"}},"vacillate":{"collins":{"senses":[{"pos":"VERB","cn":"犹豫不定;踌躇;拿不定主意","en":"If you vacillate between two alternatives or choices, you keep changing your mind. 【语法信息】：V between pl-n 【语法信息】：V 【语域标签】：FORMAL 正式 She s between men twice her age and men younger than she... 她犹豫不决，不知道是该选择年龄比她大一倍的男人还是比她小的男人。 We cannot on the"}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to keep changing your mind about what you believe or what you are going to do, especially when you have two choices and you cannot decide which one is best","cn":""},{"en":"someone who is fickle is always changing their mind about the people or things that they like so you cannot depend on them","cn":""},{"en":"if someone blows hot and cold about something, they keep changing their attitude so that sometimes they are eager to do it and at other times they are unwilling","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"Vacillate means to waver back and forth, unable to decide. You might vacillate between ordering waffles and pancakes at your favorite diner — it’s hard to pick just one when both are so tasty!"}]},"media":{"uk":"media/ldoce/hwd/bre/2/vacillate0205.mp3","us":"media/ldoce/hwd/ame/3/vacillate.mp3"},"examples":[{"en":"Her parents vacillated between different approaches to discipline.","cn":"她的父母在不同的管教方式之间摇摆不定。"}]},"vassal":{"collins":{"senses":[{"pos":"N-COUNT","cn":"（封建社会的）封臣","en":"In feudal society, a vassal was a man who gave military service to a lord, in return for which he was protected by the lord and received land to live on."},{"pos":"N-COUNT","cn":"附属国","en":"If you say that one country is a vassal of another, you mean that it is controlled by it. 【搭配模式】：usu sing 【语用信息】：disapproval 【FIELD标签】：WRITTEN 笔语 Opponents of the treaty argue that monetary union will turn France into a of Germany. 协定的反对者认为"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a man in the Middle Ages who was given land to live on by a lord in return for promising to work or fight for him 〔","cn":"中世纪领主下面的〕封臣﹐家臣〔对国君或领主效忠﹐作为回报获封土地〕"},{"en":"a country that is controlled by another country","cn":"附属国﹐属地"}]},"vocab":{"pos":"n","senses":[{"en":"If this were Medieval Europe, you would probably be a vassal — like most everyone else. Vassals were people who worked the vast plots of land that were held by lords, who though much fewer in number, held all the wealth and power."}]},"media":{"uk":"media/ldoce/hwd/bre/c/ld41vassal.mp3","us":"media/ldoce/hwd/ame/1/vassal.mp3"},"examples":[{"en":"a vassal state","cn":"附庸国"}]},"vacant":{"collins":{"senses":[{"pos":"ADJ","cn":"未使用的;未被占用的;空的","en":"If something is vacant , it is not being used by anyone. 【搭配模式】：usu ADJ n Half way down the coach was a seat... 车厢中部有一个空座。 In every major city there are more buildings than there are homeless people. 各大城市里空置的楼房都比无家可归的人多。"},{"pos":"ADJ","cn":"(工作或职位）空缺的","en":"If a job or position is vacant , no one is doing it or in it at present, and people can apply for it. A number of senior people were regarded as likely to occupy the now post... 几位资深人士被认为有望填补现在空缺的职位。 The post of chairman has been for some t"}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"used about a place that has no one in it or no one using it","cn":""},{"en":"used about a seat, space, or room that is available to use because no one else is using it","cn":""},{"en":"used about a room or building that is available for people to pay to use","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"You can use the adjective vacant to describe something that is empty — an apartment with no tenant or furniture, a job with no worker, or a person with no brainpower."}]},"collocations":{"phrases":["VERBS be | become, fall (only used of jobs) A seat became vacant and he sat down in it. A job fell vacant in the accounting department. | re"]},"media":{"uk":"media/ldoce/hwd/bre/e/vacant0205.mp3","us":"media/ldoce/hwd/ame/6/vacant.mp3"},"examples":[{"en":"When the post finally fell (= became) vacant, they offered it to Fiona.","cn":"这个职位最终空出来之后，他们给了菲奥纳。"},{"en":"The seat next to him was vacant.","cn":"他旁边的座位空着。"}]},"vaccination":{"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to protect a person or animal from a disease by giving them a vaccine","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Vaccination is the act of getting a shot (a vaccine) to protect you against a certain disease. If you want to protect yourself from catching the mumps, you will need to undergo a vaccination ."}]},"collocations":{"phrases":["ADJ. flu, measles, rubella, smallpox, etc.","VERB + VACCINATION have | give sb","VACCINATION + NOUN campaign, programme","PREP. ~ against a vaccination against tetanus"]},"media":{"uk":"media/ldoce/hwd/bre/6/ld41vaccinate.mp3","us":"media/ldoce/hwd/ame/b/vaccinate.mp3"},"examples":[{"en":"Make sure your vaccinations are up to date.","cn":"一定要接种最新的疫苗。"},{"en":"vaccination against typhoid","cn":"伤寒疫苗的接种"}]},"vandal":{"collins":{"senses":[{"pos":"N-COUNT","cn":"（尤指破坏公共财产的）破坏分子，捣毁者","en":"A vandal is someone who deliberately damages things, especially public property. All information systems that have been fitted at Ashford station have now been destroyed by s. 安装在阿什福德车站的所有信息查询装置如今都被破坏分子毁坏了。"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who steals things","cn":""},{"en":"someone who steals money or valuable things from a bank, shop etc – used especially when someone sees the person who is stealing","cn":""},{"en":"someone who goes into people’s homes in order to steal","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A vandal is someone who harms or destroys other people's property. Someone who paints graffiti on your door is a vandal."}]},"collocations":{"phrases":["ADJ. car Car vandals caused more than &pound; 10,000 worth of damage to vehicles last Saturday.","VERB + VANDAL deter, discourage The windows are covered with grilles to deter vandals.","VANDAL + VERB damage sth, wreck sth"]},"media":{"uk":"media/ldoce/hwd/bre/f/vandal0205.mp3","us":"media/ldoce/hwd/ame/0/vandal.mp3"}},"valet":{"collins":{"senses":[{"pos":"N-COUNT","cn":"（男子的）贴身男仆,男仆从","en":"A valet is a male servant who looks after his employer by doing things such as caring for his clothes and cooking for him."},{"pos":"VERB","cn":"(受雇）洗（车）","en":"If someone valets a vehicle, they are paid to clean it thoroughly inside and out. 【搭配模式】：V n"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a male servant who looks after a man’s clothes, serves his meals etc 〔","cn":"男子的〕贴身男仆﹐男仆从"},{"en":"someone who parks your car for you at a restaurant, hotel etc 〔","cn":"餐厅或酒店等场所〕为客人停车的人"},{"en":"someone who cleans the clothes of people staying in a hotel 〔","cn":"为酒店客人洗衣服的〕服务员"}]},"vocab":{"pos":"n v","senses":[{"en":"A valet is like a butler: a servant who attends to his employer's needs."}]},"media":{"uk":"media/ldoce/hwd/bre/d/valet_n0205.mp3","us":"media/ldoce/hwd/ame/b/valet.mp3"},"examples":[{"en":"a car valeting service","cn":"清洗汽车服务"},{"en":"valet service","cn":"代客泊车服务"}]},"variously":{"collins":{"senses":[{"pos":"ADV","cn":"不同地;以各种方式","en":"You can use variously to introduce a number of different ways in which something can be described. 【搭配模式】：usu ADV with v ...the crowds, which were estimated at two to several thousand... 人数估计不一、从两千人到数千人不等的人群 The family has been described as"}]},"ldoce":{"phon":"hwd","pos":"adverb","senses":[{"en":"in many different ways","cn":"以各种不同的方式"},{"en":"variously described as/known as/called etc something the phenomena variously known as ‘mass culture’, ‘popular culture’, or the ‘public arts’","cn":"被冠以不同名称如“大众文化”﹑“通俗文化”或“大众艺术”的现象 His fortune has been variously estimated at between $1 and $2 billion. 对他的财富有各种猜测﹐从10亿美元"}]},"media":{"uk":"media/ldoce/hwd/bre/7/brelasdevariously.mp3","us":"media/ldoce/hwd/ame/5/variously.mp3"},"examples":[{"en":"The cost has been variously estimated at between £10 million and £20 million.","cn":"对成本的估计众说纷纭，从 1 000 万英镑到 2 000 万英镑不等。"},{"en":"He has been variously described as a hero, a genius and a bully.","cn":"他被描述为英雄、天才、恶霸，不一而足。"}]},"vaginal":{"collins":{"senses":[{"pos":"ADJ","cn":"阴道的","en":"Vaginal means relating to or involving the vagina. 【搭配模式】：ADJ n The creams have been used to reduce infections. 已使用这种乳膏来减少阴道感染。"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the passage between a woman’s outer sexual organs and her uterus","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/c/vagina0205.mp3","us":"media/ldoce/hwd/ame/5/vagina.mp3"}},"vase":{"collins":{"senses":[{"pos":"N-COUNT","cn":"花瓶;（装饰用的）瓶","en":"A vase is a jar, usually made of glass or pottery, used for holding cut flowers or as an ornament. ...a of red roses. 一花瓶的红玫瑰 ...lead crystal s. 铅晶质玻璃花瓶"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a container used to put flowers in or for decoration","cn":"花瓶﹐〔装饰用的〕瓶"}]},"collocations":{"phrases":["ADJ. flower | china, crystal, cut-glass, glass, porcelain, silver, stone","VASE + VERB be filled with sth, contain sth, hold sth | stand A silver vase stood on the mantelpiece.","PREP. in a/the ~ flowers arranged in a vase | ~ of a vase of fresh flowers"]},"media":{"img":["media/ldoce/img/vase.jpg"],"uk":"media/ldoce/hwd/bre/c/vase0205.mp3","us":"media/ldoce/hwd/ame/c/vase.mp3"},"examples":[{"en":"a vase of flowers","cn":"一瓶花"}]},"vacate":{"collins":{"senses":[{"pos":"VERB","cn":"腾出（空间）;辞去（职位）","en":"If you vacate a place or a job, you leave it or give it up, making it available for other people. 【语法信息】：V n 【语域标签】：FORMAL 正式 He d the flat and went to stay with an uncle... 他搬出了公寓，住到了他的一个叔叔那里。 He recently d his post as NHS Personnel Direct"}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to leave your home or the area where you live","cn":""},{"en":"to permanently leave your home, usually one you rent or share with someone else, taking all your possessions with you","cn":""},{"en":"if a young person leaves home , they leave their parents' house because they think they are old enough to live on their own","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"If someone asks you to vacate the room, you'd better pack up your things and go. When you vacate something, you leave it behind, usually empty."}]},"media":{"uk":"media/ldoce/hwd/bre/d/vacate0205.mp3","us":"media/ldoce/hwd/ame/e/vacate.mp3"},"examples":[{"en":"Guests are requested to vacate their rooms by noon on the day of departure.","cn":"房客务请在离开之日的中午以前腾出房间。"},{"en":"Clay will vacate the position on June 19.","cn":"克莱将于6月19日离职。"}]},"valium":{"collins":{"senses":[{"pos":"N-VAR","cn":"安定(一种镇静药)","en":"Valium is a drug given to people to calm their nerves when they are very depressed or upset. TRADEMARK 商标"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a drug that makes people feel calmer and less anxious Valium","cn":"牌安定〔一种镇静药〕"}]},"media":{"uk":"media/ldoce/hwd/bre/3/valium0205.mp3","us":"media/ldoce/hwd/ame/d/valium.mp3"}},"vale":{"collins":{"senses":[{"pos":"N-COUNT","cn":"谷;山谷","en":"A vale is a valley. 【搭配模式】：oft in names 【STYLE标签】：LITERARY 文 ...a small , sheltering under mist-shrouded hills. 隐蔽在雾气笼罩的山丘下的小山谷"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a broad low valley","cn":"谷﹔山谷"},{"en":"an expression used to mean the difficulties of life","cn":"生活的磨难﹐烦恼的尘世"}]},"vocab":{"pos":"n","senses":[{"en":"A vale is a long depression in the land, usually between two hills and containing a river. A vale is a valley."}]},"media":{"uk":"media/ldoce/hwd/bre/4/ld41vale.mp3","us":"media/ldoce/hwd/ame/c/vail.mp3"},"examples":[{"en":"the Vale of the White Horse","cn":"怀特霍斯谷"},{"en":"a wooded vale","cn":"树木茂密的山谷"}]},"valedictorian":{"collins":{"senses":[{"pos":"N-COUNT","cn":"（中学或大学毕业典礼上）致告别词的优秀毕业生","en":"A valedictorian is the student who has the highest marks in their class when they graduate from high school, college, or university, and who gives a speech at their graduation ceremony. 【语域标签】：AM 美"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the student who has received the best marks all the way through school, and who usually makes a speech at the graduation ceremony","cn":"致告别词的毕业生代表〔通常为成绩最优秀者〕"}]},"vocab":{"pos":"n","senses":[{"en":"The valedictorian is usually the student with the highest grades in a class. If the valedictorian of your class is someone you like and admire, you'll enjoy listening to her graduation speech."}]},"media":{"uk":"media/ldoce/hwd/bre/e/ld41valedictorian.mp3","us":"media/ldoce/hwd/ame/c/valedictorian.mp3"}},"vagabond":{"collins":{"senses":[{"pos":"N-COUNT","cn":". 流浪汉;漂泊者;无业游民","en":"A vagabond is someone who wanders from place to place and has no home or job 【STYLE标签】：OLD-FASHIONED 过时"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who has no home and travels from place to place","cn":"流浪者﹐漂泊者"}]},"vocab":{"pos":"n adj v","senses":[{"en":"A vagabond is someone who moves around a lot. Picture Boxcar Willie, bandana on a stick thrown over his shoulder, going wherever the breeze takes him."}]},"media":{"uk":"media/ldoce/hwd/bre/8/ld41vagabond.mp3","us":"media/ldoce/hwd/ame/6/vagabond.mp3"}},"vacancy":{"collins":{"senses":[{"pos":"N-COUNT","cn":"（工作或职位的）空缺","en":"A vacancy is a job or position which has not been filled. They had a short-term for a person on the foreign desk... 他们在国际新闻组有一个短期的空缺职位。 Most vacancies are at senior level, requiring appropriate qualifications. 大多数空缺属于高层职位，要求具备相应的资历。"},{"pos":"N-COUNT","cn":"（旅馆里待租的）空房","en":"If there are vacancies at a building such as a hotel, some of the rooms are available to rent. This year hotels that usually are jammed had vacancies all summer. 今年,那些通常爆满的旅店整个夏天都有空客房。"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the regular paid work that you do for an employer","cn":""},{"en":"activities that you are paid for doing – used either when you work for an employer or when you work in your own business","cn":""},{"en":"a job for which you need special education and training","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Vacancy refers to something being unoccupied. If a hotel has vacancies , there are rooms available."}]},"collocations":{"phrases":["ADJ. unfilled | suitable The agency will let you know if they have any suitable vacancies. | casual, temporary | job, presidential, senate, ","VERB + VACANCY have | create, leave Her going on maternity leave will create a temporary vacancy. | fill","VACANCY + VERB arise, exist, occur A vacancy has arisen in our sales department.","PREP. ~ for a vacancy for head chef | ~ in a vacancy in the catering department"]},"media":{"uk":"media/ldoce/hwd/bre/4/vacancy0205.mp3","us":"media/ldoce/hwd/ame/4/vacancy.mp3"},"examples":[{"en":"I'm sorry, we have no vacancies.","cn":"对不起，我们这里客满。"},{"en":"the vacancy of her expression","cn":"她那茫然若失的表情"}]},"varnish":{"collins":{"senses":[{"pos":"N-MASS","cn":"（涂在木头或其他材料表面的）清漆,罩光漆","en":"Varnish is an oily liquid which is painted onto wood or other material to give it a hard, clear, shiny surface. The comes in six natural wood shades. 有6种深浅不同的天然木质色泽的清漆可选。"},{"pos":"N-SING","cn":"（涂了清漆后的）漆面，光泽面","en":"The varnish on an object is the hard, clear, shiny surface that it has when it has been painted with varnish. He brought out the fiddle, its cracked and blistered. 他取出了小提琴，它表面的清漆已出现裂缝，还起了浮泡。"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a clear liquid that is painted onto things, especially things made of wood, to protect them, or the hard shiny surface produced by this 〔","cn":"尤指刷在木制品上的〕清漆﹐罩光漆﹔光泽的表面"},{"en":"to cover something with varnish","cn":"给…涂上清漆"}]},"vocab":{"pos":"n v","senses":[{"en":"Varnish is a shiny coating that's painted on a floor or piece of furniture and then dries clear and luminous. After refinishing an old oak chair, you might apply a coat of varnish . (Just don't sit on it until it's dry.)"}]},"collocations":{"phrases":["ADJ. clear, colourless, transparent | gloss, glossy | matt (see also nail varnish)","QUANT. coat The table needed two coats of varnish.","VERB + VARNISH apply Apply the varnish evenly over the whole surface. | remove, scrape off, strip off","VARNISH + VERB dry | protect sth You need a good quality varnish to protect the timber.","VARNISH + NOUN remover"]},"media":{"uk":"media/ldoce/hwd/bre/1/varnish_n0205.mp3","us":"media/ldoce/hwd/ame/7/varnish1.mp3"},"examples":[{"en":"Her nails were varnished a brilliant shade of red.","cn":"她的指甲上涂了一层鲜亮的红指甲油。"},{"en":"( BrE ) Josie was sitting at her desk, varnishing her nails.","cn":"乔西坐在书桌旁，涂着指甲油。"}]},"vane":{"collins":{"senses":[{"pos":"N-COUNT","cn":"（靠风力或水力驱动机器的)翼，叶片，轮叶","en":"; A vane is a flat blade which pushes or is pushed by wind or water, and forms part of a machine such as a fan, a windmill, or a ship's propeller."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a flat blade that is moved by wind or water to produce power to drive a machine 〔","cn":"靠风力或水力驱动﹑为机器产生动力的〕翼﹐叶片"}]},"vocab":{"pos":"n","senses":[{"en":"Vane is usually short for “weathervane.” If the vane on top of the building is spinning, it must be windy outside."}]},"media":{"uk":"media/ldoce/hwd/bre/3/ld41vane.mp3","us":"media/ldoce/hwd/ame/1/vain.mp3"}},"variant":{"collins":{"senses":[{"pos":"N-COUNT","cn":"变体;变种;变化形式","en":"A variant of a particular thing is something that has a different form to that thing, although it is related to it. 【搭配模式】：usu with supp The quagga was a strikingly beautiful of the zebra... 斑驴是一种极美丽的斑马变种。 An intriguing to pipelines would b"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"one more of the same kind of thing or person","cn":""},{"en":"different ones from the ones that you already have, or that you have already mentioned","cn":""},{"en":"use this about several people or things of the same general type, when you are comparing them with each other and noticing the differences between them","cn":""}]},"vocab":{"pos":"n adj","senses":[{"en":"A variant is another version of something. You could say chimps and apes and gorillas are variants in the primate family."}]},"media":{"uk":"media/ldoce/hwd/bre/5/variant0205.mp3","us":"media/ldoce/hwd/ame/6/variant1.mp3"},"examples":[{"en":"This game is a variant of baseball.","cn":"这种运动是由棒球演变而来的。"},{"en":"variant forms of spelling","cn":"不同的拼写形式"}]},"vanguard":{"collins":{"senses":[{"pos":"N-SING","cn":"（革命或研究的）前沿；先锋，先驱","en":"If someone is in the vanguard of something such as a revolution or an area of research, they are involved in the most advanced part of it. You can also refer to the people themselves as the vanguard . 【搭配模式】：usu the N Such thinking puts Kod"},{"pos":"N-SING","cn":"先头部队;尖兵","en":"The vanguard of an army is the part of it that goes into battle first. 【搭配模式】： the N ...a force of mobile reserve units that could strike quickly and effectively at the of an invading army. 能够对入侵的先头部队进行快速有效反击的机动预备部队"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"in the most advanced position of development","cn":"在(某事物的)前沿"},{"en":"the leading position at the front of an army or group of ships moving into battle, or the soldiers who are in this position 〔","cn":"军队或舰队的〕前卫﹐前锋"}]},"vocab":{"pos":"n","senses":[{"en":"If you are in the vanguard , you're up front. It could be that you are in the vanguard of an advancing army, or in the vanguard of any movement, trend, or occupation."}]},"media":{"uk":"media/ldoce/hwd/bre/6/vanguard0205.mp3","us":"media/ldoce/hwd/ame/c/vanguard.mp3"},"examples":[{"en":"The company is proud to be in the vanguard of scientific progress.","cn":"这家公司以处于科学发展的领先地位而自豪。"},{"en":"The shop has always been in the vanguard of London fashion trends.","cn":"那家商店一直走在伦敦时尚潮流的最前沿。"}]},"variance":{"collins":{"senses":[{"pos":"PHRASE","cn":"（与…）不一致，相矛盾","en":"If one thing is at variance with another, the two things seem to contradict each other. 【搭配模式】：v-link PHR 【语域标签】：FORMAL 正式 Many of his statements were at with the facts... 他的说法有很多和事实不符。 This idealistic concept is at with reality. 这种理想主义的观念和"},{"pos":"N-VAR","cn":"差异;不同","en":"The variance between things is the difference between them. 【搭配模式】：usu with supp 【语域标签】：FORMAL 正式 ...the s in the stock price. 股票价格的变化 ...total revenue . 总收入的差异"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"if two people or things are at variance with each other, they do not agree or are very different (","cn":"与某人/某事物)有分歧﹔(与某人/某事物)有冲突"},{"en":"the amount by which two or more things are different or by which they change 〔","cn":"数量的〕差异﹐不一致﹐变化幅度"},{"en":"the official permission to do something different from what is normally allowed","cn":"豁免﹐特免"}]},"vocab":{"pos":"n","senses":[{"en":"A change to the norm is called a variance . It suggests a difference or shifting away from the expected or usual, an example being snow in July, which is a variance in the weather of the United States, even in Minnesota."}]},"media":{"uk":"media/ldoce/hwd/bre/8/variance0205.mp3","us":"media/ldoce/hwd/ame/8/variance.mp3"},"examples":[{"en":"These conclusions are totally at variance with the evidence.","cn":"这些结论与证据完全相悖。"},{"en":"a note with subtle variances of pitch","cn":"音高有细微变化的音符"}]},"vain":{"collins":{"senses":[{"pos":"ADJ","cn":"徒劳的;无效的;不成功的","en":"A vain attempt or action is one that fails to achieve what was intended. 【搭配模式】：ADJ n The drafting committee worked through the night in a attempt to finish on schedule... 起草委员会为按计划完成草案已通宵加班，但结果仍是徒劳。 I was singing in a effort to cheer him u"},{"pos":"ADJ","cn":"徒然的;无望的","en":"If you describe a hope that something will happen as a vain hope, you mean that there is no chance of it happening. 【搭配模式】：ADJ n He married his fourth wife, Susan, in the hope that she would improve his health. 他娶了第四个老婆苏珊，徒然希望她能使他健康状况好转。"}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"very pleased with what you, your family, or your country have achieved, or of something you own","cn":""},{"en":"feeling pleased because something good has happened, especially because you think you have been very clever, skilful etc","cn":""},{"en":"behaving in an unpleasant and annoying way, because you think you are better or know more than other people, and that your opinions are always right","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"If you spend all day admiring yourself in reflective surfaces — mirrors, pools of water, the backs of spoons — people may think you are conceited or vain ."}]},"media":{"uk":"media/ldoce/hwd/bre/2/vain0205.mp3","us":"media/ldoce/hwd/ame/1/vain.mp3"},"examples":[{"en":"I knocked loudly in the vain hope that someone might answer.","cn":"我敲门敲得很响，希望有人应声，却是徒然。"},{"en":"They tried in vain to persuade her to go.","cn":"他们极力劝说她去，但枉费了一番口舌。"}]},"valuation":{"collins":{"senses":[{"pos":"N-VAR","cn":"估价;估值","en":"A valuation is a judgment that someone makes about how much money something is worth. ...an independent of the company... 对这家公司的独立评估 The s reflect prices at 1 April 1991... 这些估值反映了1991年4月1日的价格水平。 Valuation lies at the heart of all takeovers"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a professional judgment about how much something is worth 〔","cn":"专业的〕估价﹐估值"},{"en":"a judgment about how effective or useful a particular idea or plan will be 〔","cn":"对某个想法﹑计划的〕评价﹐评估"}]},"collocations":{"phrases":["ADJ. high, low | detailed | independent | actuarial | market | land, mortgage, property | share, stock","VERB + VALUATION carry out, do, make, prepare","VALUATION + NOUN fee, report"]},"media":{"uk":"media/ldoce/hwd/bre/5/valuation0205.mp3","us":"media/ldoce/hwd/ame/9/valuation.mp3"},"examples":[{"en":"Surveyors carried out a valuation of the property.","cn":"鉴定人员对这处房产作了估价。"},{"en":"Experts set a high valuation on the painting.","cn":"专家对这幅画估价很高。"}]},"valve":{"collins":{"senses":[{"pos":"N-COUNT","cn":"阀;活门","en":"A valve is a device attached to a pipe or a tube which controls the flow of air or liquid through the pipe or tube."},{"pos":"N-COUNT","cn":"（心脏的）瓣，瓣膜","en":"A valve is a small piece of tissue in your heart or in a vein which controls the flow of blood and keeps it flowing in one direction only. He also has problems with a heart . 他的一个心瓣也有毛病。"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a part of a tube or pipe that opens and shuts like a door to control the flow of liquid, gas, air etc passing through it","cn":"阀﹐活门﹔气嘴﹔瓣(膜)"},{"en":"the part on a trumpet or similar musical instrument that you press to change the sound of the note 〔","cn":"小号等乐器上的〕阀键﹐活塞"},{"en":"a closed glass tube used to control the flow of electricity in old radios, televisions etc","cn":"电子管﹐真空管"}]},"collocations":{"phrases":["ADJ. safety | non-return, one-way | drain, pressure-relief | fuel, water, etc. | heart, radiator, etc.","VERB + VALVE fit The plumber will fit some new safety valves. | open You need special tools to open the valve. | close"]},"media":{"img":["media/ldoce/img/valve.jpg","media/ldoce/img/bugle.jpg"],"uk":"media/ldoce/hwd/bre/3/valve0205.mp3","us":"media/ldoce/hwd/ame/4/valve.mp3"},"examples":[{"en":"heart valves","cn":"心脏瓣膜"}]},"vaudeville":{"collins":{"senses":[{"pos":"N-UNCOUNT","cn":"歌舞杂耍表演,综艺节目（尤流行于20世纪初）","en":"Vaudeville is a type of entertainment consisting of short acts such as comedy, singing, and dancing. Vaudeville was especially popular in the early part of the twentieth century. 【语域标签】：mainly AM 主美 In 1901, he broke out of and set his sigh"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a type of theatre entertainment, popular from the 1880s to the 1950s, in which there were many short performances of different kinds, including singing, dancing, jokes etc","cn":"歌舞杂耍表演〔盛行于19世纪80年代至20世纪50年代的一种剧院娱乐节目﹐有演唱﹑舞蹈﹑笑话等〕"}]},"vocab":{"pos":"n","senses":[{"en":"Vaudeville is a type of entertainment that mixes comedy and music in a variety show."}]},"media":{"uk":"media/ldoce/hwd/bre/b/ld41vaudeville.mp3","us":"media/ldoce/hwd/ame/8/vaudeville.mp3"}}});
